/// Render one pending act as a line for the list.
#[must_use]
pub fn line(p: &Pending) -> String {
    let base = line_of(p);
    match p {
        Pending::Resolve {
            assignment: Some(Ok(n)),
            ..
        } => format!("{base}  [assigned: {}]", assigned_names(n)),
        Pending::Resolve {
            assignment: Some(Err(f)),
            ..
        } => format!("{base}  [{}]", f.rule),
        _ => base,
